//! Parity tests for `gpt_sovits_text::japanese` against fixtures generated by
//! `parity/japanese/gen_fixtures.py`.
//!
//! Every layer of the pipeline is compared for every input. The inputs whose
//! output differs from upstream are listed per fixture and layer in
//! the `exc` module at the end of this file, grouped by cause (see
//! `parity/japanese/README.md`); a test
//! fails both on a new mismatch and on a listed input that now matches.
//!
//! Environment variables for debugging: `JA_VERBOSE=1` prints every mismatch,
//! `JA_LABEL_DIFF=1` prints the label fields that differ, `JA_DUMP=1` prints
//! the mismatch lists.

use std::collections::{BTreeMap, BTreeSet};

use gpt_sovits_text::japanese::{self, pyopenjtalk};
use serde_json::Value;

fn load(name: &str) -> Vec<Value> {
  let path = format!(
    "{}/tests/fixtures/japanese/{name}",
    env!("CARGO_MANIFEST_DIR")
  );
  std::fs::read_to_string(&path)
    .unwrap_or_else(|e| panic!("{path}: {e}"))
    .lines()
    .map(|l| serde_json::from_str(l).unwrap())
    .collect()
}

/// NJD feature string without `orig` (column 7), which jpreprocess does not keep.
fn njd_without_orig(s: &str) -> String {
  let mut cols: Vec<&str> = s.split(',').collect();
  if cols.len() > 7 {
    cols.remove(7);
  }
  cols.join(",")
}

/// [`njd_without_orig`], plus the notations that differ without changing the
/// meaning: `chain_rule` is a set of rules where `@0` is the default accent
/// shift and `-1` means no rule (jpreprocess prints the rules in its own
/// order, once each, without `@0`, and `*` for none), and `chain_flag` `-1`
/// (unset) and `0` both mean "not chained".
fn njd_normalized(s: &str) -> String {
  let cols: Vec<&str> = s.split(',').collect();
  if cols.len() != 13 {
    return njd_without_orig(s);
  }
  let rules = if cols[11] == "-1" { "*" } else { cols[11] };
  let mut rules: Vec<&str> = rules
    .split('/')
    .map(|r| r.strip_suffix("@0").unwrap_or(r))
    .collect();
  rules.sort_unstable();
  rules.dedup();
  let rules = rules.join("/");
  let flag = if cols[12] == "-1" { "0" } else { cols[12] };
  let mut out: Vec<&str> = cols[..7].to_vec();
  out.extend_from_slice(&cols[8..11]);
  out.push(&rules);
  out.push(flag);
  out.join(",")
}

/// Labels without the `/B:`, `/C:` and `/D:` fields (part of speech,
/// conjugation type and form of the previous, current and next word).
/// `pyopenjtalk_g2p_prosody` does not read them, and jpreprocess fills them
/// differently from Open JTalk (see `parity/japanese/README.md`).
fn without_pos_fields(labels: &[String]) -> Vec<String> {
  labels
    .iter()
    .map(|l| match (l.find("/B:"), l.find("/E:")) {
      (Some(start), Some(end)) => format!("{}{}", &l[..start], &l[end..]),
      _ => l.clone(),
    })
    .collect()
}

/// Prints which label fields differ, for localizing mismatches.
fn label_field_diffs(text: &str, want: &[String], got: &[String]) {
  if want.len() != got.len() {
    eprintln!("LDIFF {text:?} len {} vs {}", want.len(), got.len());
    return;
  }
  for (i, (w, g)) in want.iter().zip(got).enumerate() {
    for (a, b) in w.split('/').zip(g.split('/')) {
      if a != b {
        let pos = match i {
          0 => "first",
          _ if i + 1 == want.len() => "last",
          _ => "mid",
        };
        eprintln!("LDIFF {text:?} {pos} {a} -> {b}");
      }
    }
  }
}

fn strings(v: &Value) -> Option<Vec<String>> {
  v.as_array()
    .map(|a| a.iter().map(|x| x.as_str().unwrap().to_string()).collect())
}

/// Layers whose rate is printed but whose mismatches are not listed: they
/// differ only in notation or in label fields that nothing reads, and the
/// asserted layers `njd (normalized)` and `labels without /B: /C: /D:` cover
/// everything else.
const DIAGNOSTIC_LAYERS: &[&str] = &["njd", "labels"];

/// Cases and mismatching inputs per layer.
struct Report {
  name: &'static str,
  cases: BTreeMap<&'static str, usize>,
  mismatches: BTreeMap<&'static str, BTreeSet<String>>,
  failed: BTreeMap<&'static str, usize>,
}

impl Report {
  fn new(name: &'static str) -> Self {
    Self {
      name,
      cases: BTreeMap::new(),
      mismatches: BTreeMap::new(),
      failed: BTreeMap::new(),
    }
  }

  fn check<T: PartialEq + std::fmt::Debug>(
    &mut self,
    layer: &'static str,
    input: &str,
    want: T,
    got: T,
  ) {
    *self.cases.entry(layer).or_default() += 1;
    let set = self.mismatches.entry(layer).or_default();
    if want != got {
      if std::env::var("JA_VERBOSE").is_ok() {
        eprintln!("[{layer}] {input:?}\n  want {want:?}\n  got  {got:?}");
      }
      *self.failed.entry(layer).or_default() += 1;
      set.insert(input.to_string());
    }
  }

  /// Prints the exact-match rate of every layer and asserts that the
  /// mismatching inputs of each layer are exactly the documented ones.
  fn finish(&self, expected: &[(&str, &[&str])]) {
    let dump = std::env::var("JA_DUMP").is_ok();
    for (layer, n) in &self.cases {
      let bad = self.failed.get(layer).copied().unwrap_or(0);
      eprintln!("{} {layer}: {}/{n} exact", self.name, n - bad);
      if dump {
        let list: Vec<&String> = self.mismatches[layer].iter().collect();
        eprintln!("DUMP {} {layer:?} => &{list:?},", self.name);
      }
    }
    let mut errors = Vec::new();
    for (layer, set) in &self.mismatches {
      if DIAGNOSTIC_LAYERS.contains(layer) {
        continue;
      }
      let want: BTreeSet<String> = expected
        .iter()
        .filter(|(l, _)| l == layer)
        .flat_map(|(_, inputs)| inputs.iter().map(|s| s.to_string()))
        .collect();
      let unexpected: Vec<&String> = set.difference(&want).collect();
      let fixed: Vec<&String> = want.difference(set).collect();
      if !unexpected.is_empty() {
        errors.push(format!("{layer}: unexpected mismatches {unexpected:?}"));
      }
      if !fixed.is_empty() {
        errors.push(format!("{layer}: listed exceptions now match {fixed:?}"));
      }
    }
    for (layer, _) in expected {
      assert!(
        self.cases.contains_key(layer),
        "{}: exception list for unknown layer {layer}",
        self.name
      );
    }
    assert!(errors.is_empty(), "{}:\n{}", self.name, errors.join("\n"));
  }
}

fn check_layers(report: &mut Report, seg: &Value) {
  let text = seg["text"].as_str().unwrap();
  let njd = pyopenjtalk::run_frontend(text).unwrap();
  if let Some(want) = strings(&seg["njd"]) {
    let got: Vec<String> = njd.iter().map(|n| n.to_string()).collect();
    report.check(
      "njd",
      text,
      want.iter().map(|s| njd_without_orig(s)).collect::<Vec<_>>(),
      got.iter().map(|s| njd_without_orig(s)).collect(),
    );
    report.check(
      "njd (normalized)",
      text,
      want.iter().map(|s| njd_normalized(s)).collect::<Vec<_>>(),
      got.iter().map(|s| njd_normalized(s)).collect(),
    );
  }
  if let Some(want) = strings(&seg["labels"]) {
    let got = pyopenjtalk::make_label(&njd);
    if std::env::var("JA_LABEL_DIFF").is_ok() {
      label_field_diffs(text, &want, &got);
    }
    report.check(
      "labels without /B: /C: /D:",
      text,
      without_pos_fields(&want),
      without_pos_fields(&got),
    );
    report.check("labels", text, want, got);
  }
  report.check(
    "pyopenjtalk.g2p",
    text,
    seg["g2p_plain"].as_str().unwrap().to_string(),
    pyopenjtalk::g2p(text).unwrap(),
  );
  report.check(
    "pyopenjtalk_g2p_prosody",
    text,
    strings(&seg["prosody"]),
    japanese::pyopenjtalk_g2p_prosody(text, true).ok(),
  );
}

fn check_frontend(report: &mut Report, rec: &Value) {
  let text = rec["text"].as_str().unwrap();
  let norm = japanese::text_normalize(text);
  report.check("text_normalize", text, rec["norm"].as_str().unwrap(), &norm);
  report.check(
    "g2p",
    text,
    strings(&rec["g2p"]),
    japanese::g2p(&norm, true).ok(),
  );
  report.check(
    "g2p(with_prosody=False)",
    text,
    strings(&rec["g2p_noprosody"]),
    japanese::g2p(&norm, false).ok(),
  );
  for seg in rec["segs"].as_array().unwrap() {
    check_layers(report, seg);
  }
}

#[test]
fn corpus() {
  let mut report = Report::new("corpus");
  for rec in load("corpus.jsonl") {
    check_frontend(&mut report, &rec);
  }
  report.finish(exc::CORPUS);
}

#[test]
fn bulk_phrase() {
  let mut report = Report::new("bulk_phrase");
  for rec in load("bulk_phrase.jsonl") {
    check_frontend(&mut report, &rec);
  }
  report.finish(exc::BULK_PHRASE);
}

#[test]
fn bulk_random() {
  let mut report = Report::new("bulk_random");
  for rec in load("bulk_random.jsonl") {
    check_frontend(&mut report, &rec);
  }
  report.finish(exc::BULK_RANDOM);
}

#[test]
fn bulk_userdict() {
  let mut report = Report::new("bulk_userdict");
  for rec in load("bulk_userdict.jsonl") {
    check_layers(&mut report, &rec);
    let text = rec["text"].as_str().unwrap();
    report.check(
      "g2p",
      text,
      strings(&rec["g2p"]),
      japanese::g2p(text, true).ok(),
    );
  }
  report.finish(exc::BULK_USERDICT);
}

#[test]
fn text_normalize() {
  let records = load("text_normalize.jsonl");
  assert_eq!(records.len(), 1000);
  for rec in records {
    let text = rec["text"].as_str().unwrap();
    assert_eq!(
      japanese::text_normalize(text),
      rec["norm"].as_str().unwrap(),
      "{text:?}"
    );
    assert_eq!(
      japanese::replace_consecutive_punctuation(text),
      rec["rcp"].as_str().unwrap(),
      "{text:?}"
    );
    assert_eq!(
      japanese::symbols_to_japanese(text),
      rec["stj"].as_str().unwrap(),
      "{text:?}"
    );
  }
}

#[test]
fn post_replace_ph() {
  for rec in load("post_replace_ph.jsonl") {
    let ph = rec["ph"].as_str().unwrap();
    assert_eq!(
      japanese::post_replace_ph(ph),
      rec["out"].as_str().unwrap(),
      "{ph:?}"
    );
  }
}

#[test]
fn tokenize_csv() {
  // MeCab `tokenizeCSV` semantics used by `mecab_dict_index`.
  assert_eq!(
    pyopenjtalk::tokenize_csv("a,b,c,d,e,f,g", 5),
    ["a", "b", "c", "d", "e,f,g"]
  );
  assert_eq!(
    pyopenjtalk::tokenize_csv("\"x\"\"y\"z,  b,c", 5),
    ["x\"y", "b", "c"]
  );
  assert_eq!(pyopenjtalk::tokenize_csv("a,,b", 5), ["a", "", "b"]);
  assert_eq!(pyopenjtalk::tokenize_csv("a,b,", 5), ["a", "b"]);
}

